from typing import List


def min_absolute_difference(nums: List[int], k: int) -> int:
    """Return the minimum |k - OR(subarray)| over all non-empty subarrays."""
    best = float("inf")
    ending_ors = set()

    for value in nums:
        # ORs of subarrays ending here consist of the singleton and each
        # previous ending OR extended by this value.
        ending_ors = {value} | {previous | value for previous in ending_ors}
        for current_or in ending_ors:
            best = min(best, abs(k - current_or))
            if best == 0:
                return 0

    return int(best) if best != float("inf") else 0

